function checkPerfectNumber(num) {
  if (num === 1) {
    return false;
  }
  let sum = 1;
  for (let divisor = 2; divisor * divisor <= num; divisor++) {
    if (num % divisor === 0) {
      sum += divisor;
      const partner = num / divisor;
      if (partner !== divisor) {
        sum += partner;
      }
    }
  }
  return sum === num;
}

