function checkPerfectNumber(num) {
  // A different route than summing divisor pairs: factor num and multiply the divisor sums of its prime
  // powers, σ(p^k) = 1 + p + ... + p^k. num is perfect when σ(num) - num === num.
  let rest = num;
  let sigma = 1;
  for (let p = 2; p * p <= rest; p++) {
    let power = 1;
    let sum = 1;
    while (rest % p === 0) {
      rest /= p;
      power *= p;
      sum += power;
    }
    sigma *= sum;
  }
  if (rest > 1) sigma *= rest + 1;
  return sigma - num === num;
}

