function generate(rand, size) {
  const perfect = [6, 28, 496, 8128, 33550336];
  if (size === 'small') {
    if (rand() < 0.3) return [perfect[Math.floor(rand() * 4)]];
    return [1 + Math.floor(rand() * 2000)];
  }
  const roll = rand();
  if (roll < 0.25) return [33550336];
  if (roll < 0.5) {
    // A perfect square near the top, so the divisor and its partner meet.
    const root = 5000 + Math.floor(rand() * 5000);
    return [root * root];
  }
  return [1 + Math.floor(rand() * 100000000)];
}
